    /**
     * Use this method to send static .WEBP, animated .TGS, or video .WEBM stickers. On success, the sent Message is returned.
     *
     * @param chat_id Unique identifier for the target chat or username of the target channel (in the format @channelusername)
     * @param sticker Sticker to send. Pass a file_id as String to send a file that exists on the Telegram servers (recommended), pass an HTTP URL as a String for Telegram to get a .WEBP sticker from the Internet, or upload a new .WEBP, .TGS, or .WEBM sticker using multipart/form-data. More information on Sending Files ». Video and animated stickers can't be sent via an HTTP URL.
     * @param business_connection_id Unique identifier of the business connection on behalf of which the message will be sent
     * @param message_thread_id Unique identifier for the target message thread (topic) of the forum; for forum supergroups only
     * @param direct_messages_topic_id Identifier of the direct messages topic to which the message will be sent; required if the message is sent to a direct messages chat
     * @param emoji Emoji associated with the sticker; only for just uploaded stickers
     * @param disable_notification Sends the message silently. Users will receive a notification with no sound.
     * @param protect_content Protects the contents of the sent message from forwarding and saving
     * @param allow_paid_broadcast Pass True to allow up to 1000 messages per second, ignoring broadcasting limits for a fee of 0.1 Telegram Stars per message. The relevant Stars will be withdrawn from the bot's balance
     * @param message_effect_id Unique identifier of the message effect to be added to the message; for private chats only
     * @param suggested_post_parameters A JSON-serialized object containing the parameters of the suggested post to send; for direct messages chats only. If the message is sent as a reply to another suggested post, then that suggested post is automatically declined.
     * @param reply_parameters Description of the message to reply to
     * @param reply_markup Additional interface options. A JSON-serialized object for an inline keyboard, custom reply keyboard, instructions to remove a reply keyboard or to force a reply from the user
     *
     * @return Message
     */
    TelegramResponse<Message> sendSticker(    std::string chat_id,
        std::string sticker,
        std::optional<std::string> business_connection_id,
        std::optional<std::int64_t> message_thread_id,
        std::optional<std::int64_t> direct_messages_topic_id,
        std::optional<std::string> emoji,
        std::optional<bool> disable_notification,
        std::optional<bool> protect_content,
        std::optional<bool> allow_paid_broadcast,
        std::optional<std::string> message_effect_id,
        std::optional<SuggestedPostParameters> suggested_post_parameters,
        std::optional<ReplyParameters> reply_parameters,
        std::optional<KeyboardOption> reply_markup
    ) {
        json j;
        j["chat_id"] = chat_id;
        j["sticker"] = sticker;
        if (business_connection_id.has_value()) {
            j["business_connection_id"] = business_connection_id.value();
        }
        if (message_thread_id.has_value()) {
            j["message_thread_id"] = message_thread_id.value();
        }
        if (direct_messages_topic_id.has_value()) {
            j["direct_messages_topic_id"] = direct_messages_topic_id.value();
        }
        if (emoji.has_value()) {
            j["emoji"] = emoji.value();
        }
        if (disable_notification.has_value()) {
            j["disable_notification"] = disable_notification.value();
        }
        if (protect_content.has_value()) {
            j["protect_content"] = protect_content.value();
        }
        if (allow_paid_broadcast.has_value()) {
            j["allow_paid_broadcast"] = allow_paid_broadcast.value();
        }
        if (message_effect_id.has_value()) {
            j["message_effect_id"] = message_effect_id.value();
        }
        if (suggested_post_parameters.has_value()) {
            j["suggested_post_parameters"] = suggested_post_parameters.value();
        }
        if (reply_parameters.has_value()) {
            j["reply_parameters"] = reply_parameters.value();
        }
        if (reply_markup.has_value()) {
            j["reply_markup"] = reply_markup.value();
        }
        std::string body = j.dump();
        std::string response = makeRequest("sendSticker", body);
        return parseResponse<Message>(response);
    }

